package com.debttracker;

/**
 * Per-account progress, saved to the RuneLite profile as JSON.
 */
class DebtState
{
	String debtItem = "";
	long marketPrice;
	boolean paidNotified;
	WealthLedger ledger = new WealthLedger();

	void startDebt(String item)
	{
		debtItem = item;
		marketPrice = 0;
		paidNotified = false;
		ledger.rebaseline();
	}
}

package com.debttracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(DebtTrackerConfig.GROUP)
public interface DebtTrackerConfig extends Config
{
	String GROUP = "debttracker";
	String START_OVER = "startOver";

	@ConfigItem(
		keyName = "debtItem",
		name = "Debt item",
		description = "What you are paying off, e.g. Berserker ring. Changing this starts a new debt from zero.",
		position = 1
	)
	default String debtItem()
	{
		return "";
	}

	@ConfigItem(
		keyName = "debtAmount",
		name = "Debt amount",
		description = "How much you owe, e.g. 2.8m or 500k. Leave blank to use the item's Grand Exchange price.",
		position = 2
	)
	default String debtAmount()
	{
		return "";
	}

	@ConfigItem(
		keyName = START_OVER,
		name = "Start over",
		description = "Tick to reset progress on the current debt to zero.",
		position = 3
	)
	default boolean startOver()
	{
		return false;
	}
}

package com.debttracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.SplitComponent;

class DebtTrackerOverlay extends OverlayPanel
{
	private static final Color BAR_PAYING = new Color(214, 158, 46);
	private static final Color BAR_PAID = new Color(56, 161, 105);
	private static final Color BAR_BACKGROUND = new Color(61, 56, 48);
	private static final Color TEXT_LOSS = new Color(240, 90, 80);
	private static final Color TEXT_WARNING = new Color(250, 200, 80);

	private final DebtTrackerPlugin plugin;

	@Inject
	DebtTrackerOverlay(DebtTrackerPlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.hasDebt())
		{
			return null;
		}

		LineComponent title = LineComponent.builder().left(plugin.getDebtName()).leftColor(Color.WHITE).build();
		BufferedImage icon = plugin.getItemIcon();
		panelComponent.getChildren().add(icon == null ? title : SplitComponent.builder()
			.first(new ImageComponent(icon))
			.second(title)
			.orientation(ComponentOrientation.HORIZONTAL)
			.gap(new Point(4, 0))
			.build());

		long amount = plugin.getDebtAmount();
		if (plugin.isAmountInvalid() || amount <= 0)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(plugin.isAmountInvalid() ? "Check debt amount" : "Set a debt amount")
				.leftColor(TEXT_WARNING)
				.build());
			return super.render(graphics);
		}

		long profit = plugin.getProfit();
		boolean paid = profit >= amount;

		ProgressBarComponent bar = new ProgressBarComponent();
		bar.setMaximum(amount);
		bar.setValue(Math.max(0, Math.min(profit, amount)));
		bar.setForegroundColor(paid ? BAR_PAID : BAR_PAYING);
		bar.setBackgroundColor(BAR_BACKGROUND);
		panelComponent.getChildren().add(bar);

		panelComponent.getChildren().add(LineComponent.builder()
			.left(GpFormat.format(profit) + " / " + GpFormat.format(amount))
			.leftColor(profit < 0 ? TEXT_LOSS : Color.WHITE)
			.build());
		panelComponent.getChildren().add(paid
			? LineComponent.builder().left("Paid off!").leftColor(BAR_PAID).right("+" + GpFormat.format(profit - amount)).rightColor(BAR_PAID).build()
			: LineComponent.builder().left("Left:").right(GpFormat.format(amount - profit)).build());

		if (!plugin.isBankSynced())
		{
			panelComponent.getChildren().add(LineComponent.builder().left("Open bank to sync").leftColor(TEXT_WARNING).build());
		}

		return super.render(graphics);
	}
}

package com.debttracker;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.text.ParseException;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.http.api.item.ItemPrice;

@Slf4j
@PluginDescriptor(
	name = "Debt Tracker",
	description = "Shows a bar that fills up as your profit pays off an item you are in debt for",
	tags = {"profit", "money", "debt", "overlay", "gp"}
)
public class DebtTrackerPlugin extends Plugin
{
	private static final String STATE_KEY = "state";
	private static final int SAVE_INTERVAL_TICKS = 10;
	private static final int PRICE_REFRESH_TICKS = 100;
	private static final int GE_LOGIN_BURST_TICKS = 3;

	private static final Map<Integer, String> TRACKED_CONTAINERS = Map.of(
		InventoryID.INV, WealthLedger.INVENTORY,
		InventoryID.WORN, WealthLedger.EQUIPMENT,
		InventoryID.BANK, WealthLedger.BANK,
		InventoryID.LOOTING_BAG, WealthLedger.LOOTING_BAG
	);

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private DebtTrackerConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private DebtTrackerOverlay overlay;

	@Inject
	private Gson gson;

	private final Map<String, Map<Integer, Long>> pending = new HashMap<>();
	private boolean offersChanged;
	private DebtState state;
	private String stateProfile;
	private boolean unsaved;
	private int ticks;
	private int ticksSinceLoad;
	private long configuredAmount;
	private int itemId = -1;

	@Getter
	private long profit;

	@Getter
	private boolean amountInvalid;

	@Getter
	private BufferedImage itemIcon;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				TRACKED_CONTAINERS.forEach((id, location) ->
				{
					ItemContainer container = client.getItemContainer(id);
					if (container != null)
					{
						pending.put(location, readItems(container));
					}
				});
				offersChanged = true;
			}
		});
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		clientThread.invoke(() ->
		{
			saveState();
			state = null;
			stateProfile = null;
			pending.clear();
			offersChanged = false;
			profit = 0;
			itemId = -1;
			itemIcon = null;
		});
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		String location = TRACKED_CONTAINERS.get(event.getContainerId());
		if (location != null)
		{
			// Applied on the next tick, so an item moving between two locations is seen in both at once
			pending.put(location, readItems(event.getItemContainer()));
		}
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		// Slots are cleared while logging in, before the real offers arrive
		if (event.getOffer().getState() != GrandExchangeOfferState.EMPTY || client.getGameState() == GameState.LOGGED_IN)
		{
			offersChanged = true;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			pending.clear();
			offersChanged = false;
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		saveState();
		state = null;
		stateProfile = null;
		profit = 0;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (DebtTrackerConfig.GROUP.equals(event.getGroup()) && event.getProfile() == null)
		{
			clientThread.invoke(this::applyConfig);
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (state == null && !loadState())
		{
			return;
		}

		ticks++;
		ticksSinceLoad++;
		boolean changed = applyObservations();
		if (ticks % PRICE_REFRESH_TICKS == 0)
		{
			resolveItem();
			changed = true;
		}
		if (changed)
		{
			refreshProfit();
		}
		if (ticks % SAVE_INTERVAL_TICKS == 0)
		{
			saveState();
		}
	}

	boolean hasDebt()
	{
		return state != null && !(config.debtItem().trim().isEmpty() && config.debtAmount().trim().isEmpty());
	}

	String getDebtName()
	{
		String item = config.debtItem().trim();
		return item.isEmpty() ? "Debt" : item;
	}

	long getDebtAmount()
	{
		return configuredAmount > 0 ? configuredAmount : state == null ? 0 : state.marketPrice;
	}

	boolean isBankSynced()
	{
		return state != null && state.ledger.hasObserved(WealthLedger.BANK);
	}

	private boolean loadState()
	{
		String profile = configManager.getRSProfileKey();
		if (profile == null)
		{
			return false;
		}

		String json = configManager.getConfiguration(DebtTrackerConfig.GROUP, profile, STATE_KEY);
		if (json != null)
		{
			try
			{
				state = gson.fromJson(json, DebtState.class);
			}
			catch (JsonParseException e)
			{
				log.warn("Discarding unreadable debt state", e);
			}
		}
		if (state == null)
		{
			state = new DebtState();
		}
		stateProfile = profile;
		ticksSinceLoad = 0;

		applyObservations();
		applyConfig();
		return true;
	}

	private void saveState()
	{
		if (state != null && unsaved)
		{
			configManager.setConfiguration(DebtTrackerConfig.GROUP, stateProfile, STATE_KEY, gson.toJson(state));
			unsaved = false;
		}
	}

	private void applyConfig()
	{
		String amount = config.debtAmount().trim();
		configuredAmount = 0;
		amountInvalid = false;
		if (!amount.isEmpty())
		{
			try
			{
				configuredAmount = QuantityFormatter.parseQuantity(amount);
				amountInvalid = configuredAmount <= 0;
			}
			catch (ParseException | NumberFormatException e)
			{
				amountInvalid = true;
			}
		}

		// Without a loaded account this runs again once one loads, so a reset is not lost
		if (state == null)
		{
			return;
		}

		itemId = -1;
		itemIcon = null;
		String item = config.debtItem().trim();
		if (config.startOver() || !item.equalsIgnoreCase(state.debtItem))
		{
			state.startDebt(item);
			unsaved = true;
		}
		resolveItem();
		refreshProfit();

		if (config.startOver())
		{
			configManager.setConfiguration(DebtTrackerConfig.GROUP, DebtTrackerConfig.START_OVER, false);
		}
	}

	private void resolveItem()
	{
		String item = config.debtItem().trim();
		if (item.isEmpty())
		{
			return;
		}

		if (itemId == -1)
		{
			// Prices load in the background after the client starts, so this can come up empty at first
			itemManager.search(item).stream()
				.min(Comparator.<ItemPrice, Boolean>comparing(p -> !p.getName().equalsIgnoreCase(item))
					.thenComparingInt(p -> p.getName().length()))
				.ifPresent(match ->
				{
					itemId = match.getId();
					itemIcon = itemManager.getImage(itemId);
				});
		}

		if (itemId != -1 && state.marketPrice == 0)
		{
			state.marketPrice = itemManager.getItemPrice(itemId);
			unsaved = true;
		}
	}

	private boolean applyObservations()
	{
		boolean changed = false;
		for (Map.Entry<String, Map<Integer, Long>> entry : pending.entrySet())
		{
			changed |= state.ledger.observe(entry.getKey(), entry.getValue());
		}
		pending.clear();

		// The slots must be recorded before the first new offer, or that offer's items would look
		// like they were already there. Waiting out the login burst keeps real offers out of the
		// empty first reading, where they would look like profit.
		boolean offersKnown = state.ledger.hasObserved(WealthLedger.GRAND_EXCHANGE);
		boolean burstOver = ticksSinceLoad > GE_LOGIN_BURST_TICKS;
		if (burstOver ? offersChanged || !offersKnown : offersChanged && offersKnown)
		{
			changed |= state.ledger.observe(WealthLedger.GRAND_EXCHANGE, readOffers());
			offersChanged = false;
		}

		unsaved |= changed;
		return changed;
	}

	private void refreshProfit()
	{
		profit = state.ledger.profit(itemManager::getItemPrice);

		long amount = getDebtAmount();
		if (amount > 0 && profit >= amount && !state.paidNotified && client.getGameState() == GameState.LOGGED_IN)
		{
			state.paidNotified = true;
			unsaved = true;
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Debt Tracker: you have paid off your " + getDebtName() + "!", null);
		}
	}

	private Map<Integer, Long> readItems(ItemContainer container)
	{
		Map<Integer, Long> items = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				items.merge(itemManager.canonicalize(item.getId()), (long) item.getQuantity(), Long::sum);
			}
		}
		return items;
	}

	private Map<Integer, Long> readOffers()
	{
		Map<Integer, Long> items = new HashMap<>();
		for (GrandExchangeOffer offer : client.getGrandExchangeOffers())
		{
			if (offer != null && offer.getState() != GrandExchangeOfferState.EMPTY)
			{
				GrandExchangeOfferState offerState = offer.getState();
				boolean buying = offerState == GrandExchangeOfferState.BUYING
					|| offerState == GrandExchangeOfferState.BOUGHT
					|| offerState == GrandExchangeOfferState.CANCELLED_BUY;
				WealthLedger.addOffer(items, ItemID.COINS, itemManager.canonicalize(offer.getItemId()), buying,
					offer.getTotalQuantity(), offer.getQuantitySold(), offer.getPrice(), offer.getSpent());
			}
		}
		items.values().removeIf(quantity -> quantity == 0);
		return items;
	}

	@Provides
	DebtTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DebtTrackerConfig.class);
	}
}

package com.debttracker;

final class GpFormat
{
	private static final long THOUSAND = 1_000L;
	private static final long MILLION = 1_000_000L;
	private static final long BILLION = 1_000_000_000L;

	private GpFormat()
	{
	}

	/**
	 * Formats gp compactly, rounding toward zero so 2,799,999 never reads as a finished 2.8M.
	 */
	static String format(long gp)
	{
		String sign = gp < 0 ? "-" : "";
		long abs = Math.abs(gp);
		if (abs >= BILLION)
		{
			return sign + scaled(abs, BILLION, 100) + "B";
		}
		if (abs >= MILLION)
		{
			return sign + scaled(abs, MILLION, 100) + "M";
		}
		if (abs >= THOUSAND)
		{
			return sign + scaled(abs, THOUSAND, 10) + "K";
		}
		return sign + abs;
	}

	private static String scaled(long value, long unit, int precision)
	{
		long whole = value / unit;
		long fraction = value % unit * precision / unit;
		if (fraction == 0)
		{
			return Long.toString(whole);
		}
		String digits = String.format(precision == 100 ? "%02d" : "%d", fraction);
		return whole + "." + digits.replaceAll("0+$", "");
	}
}

package com.debttracker;

import java.util.HashMap;
import java.util.Map;
import java.util.function.ToLongFunction;

/**
 * Tracks item quantities per storage location against a baseline. Profit is the change in total
 * quantity of each item, valued at its current price. Moving an item between locations nets to
 * zero, and items that were held all along are immune to price swings.
 */
class WealthLedger
{
	static final String INVENTORY = "inventory";
	static final String EQUIPMENT = "equipment";
	static final String BANK = "bank";
	static final String LOOTING_BAG = "lootingBag";
	static final String GRAND_EXCHANGE = "grandExchange";

	private Map<String, Map<Integer, Long>> holdings = new HashMap<>();
	private Map<String, Map<Integer, Long>> baseline = new HashMap<>();

	/**
	 * Records the contents of a location. The first time a location is seen its contents become
	 * part of the baseline, since they were not earned, they just weren't visible until now.
	 *
	 * @return true if the contents differ from what was last recorded
	 */
	boolean observe(String location, Map<Integer, Long> items)
	{
		Map<Integer, Long> previous = holdings.put(location, new HashMap<>(items));
		if (previous == null)
		{
			baseline.put(location, new HashMap<>(items));
			return true;
		}
		return !previous.equals(items);
	}

	boolean hasObserved(String location)
	{
		return holdings.containsKey(location);
	}

	/**
	 * Makes everything currently held the new starting point, so profit returns to zero.
	 */
	void rebaseline()
	{
		baseline = new HashMap<>();
		holdings.forEach((location, items) -> baseline.put(location, new HashMap<>(items)));
	}

	long profit(ToLongFunction<Integer> price)
	{
		Map<Integer, Long> change = new HashMap<>();
		holdings.values().forEach(items -> items.forEach((id, qty) -> change.merge(id, qty, Long::sum)));
		baseline.values().forEach(items -> items.forEach((id, qty) -> change.merge(id, -qty, Long::sum)));

		long profit = 0;
		for (Map.Entry<Integer, Long> entry : change.entrySet())
		{
			if (entry.getValue() != 0)
			{
				profit += entry.getValue() * price.applyAsLong(entry.getKey());
			}
		}
		return profit;
	}

	/**
	 * Adds what a Grand Exchange offer is holding on the player's behalf: unsold items and coins
	 * received for a sell offer, unspent coins and bought items for a buy offer.
	 */
	static void addOffer(Map<Integer, Long> items, int coinsId, int itemId, boolean buying, int total, int sold, long price, long spent)
	{
		long itemsHeld = buying ? sold : total - sold;
		long coinsHeld = buying ? price * total - spent : spent;
		items.merge(itemId, itemsHeld, Long::sum);
		items.merge(coinsId, coinsHeld, Long::sum);
	}
}

package com.debttracker;

import net.runelite.client.RuneLite;
