	public void depositBoxLossCorrectsWhenBankIsNextOpened()
	{
		WealthLedger ledger = startedLedger();
		ledger.observe(WealthLedger.INVENTORY, items(LOBSTER, 10));
		assertEquals(-1_000, ledger.profit(this::price));
